begin;
create temp table fixture(actor uuid default gen_random_uuid(),company uuid default gen_random_uuid(),batch uuid default gen_random_uuid(),job uuid,token uuid);
insert into fixture default values;
grant select on fixture to authenticated,service_role;
create temp table results(name text,passed boolean);
grant insert,select on results to authenticated,service_role;
create function pg_temp.ok(name text,passed boolean) returns void language plpgsql as $$begin if passed is distinct from true then raise exception 'FAILED: %',name;end if;insert into results values(name,true);end$$;
create function pg_temp.denied(name text,statement text) returns void language plpgsql as $$begin begin execute statement;exception when others then insert into results values(name,true);return;end;raise exception 'FAILED unexpectedly allowed: %',name;end$$;
insert into auth.users(id,email,email_confirmed_at,role,aud) select actor,actor::text||'@analysis-test.invalid',now(),'authenticated','authenticated' from fixture;
insert into public.companies(id,name) select company,'Analysis test' from fixture;
insert into public.company_members(company_id,user_id,role) select company,actor,'owner' from fixture;
insert into public.resume_batches(id,company_id,uploaded_by,source,file_count) select batch,company,actor,'email',1 from fixture;
do $$declare f record;r jsonb;begin
 select * into f from fixture;
 r:=public.reserve_resume(f.actor,f.company,f.batch,0,repeat('e',64),'analysis.pdf','application/pdf',10,1);
 perform public.finish_resume_upload(f.actor,f.company,(r->>'documentId')::uuid,(r->>'token')::uuid);
end$$;
select count(*) from public.claim_resume_jobs();
update fixture f set job=j.id,token=j.lease_token from public.resume_jobs j where j.company_id=f.company;
set local role service_role;
select pg_temp.ok('analysis provenance requires active lease',not public.record_resume_analysis(job,gen_random_uuid(),'{"model_requested":"fixture","prompt_version":"v2","prompt_snapshot":"synthetic instructions"}')) from fixture;
select pg_temp.ok('analysis provenance records exact prompt',public.record_resume_analysis(job,token,'{"model_requested":"fixture","prompt_version":"v2","prompt_snapshot":"synthetic instructions"}')) from fixture;
select pg_temp.ok('prompt hash computed by database',(select a.prompt_hash=encode(extensions.digest('synthetic instructions','sha256'),'hex') from public.resume_job_attempts a join fixture f on f.job=a.job_id));
select public.record_resume_analysis(job,token,'{"model_requested":"tamper","prompt_snapshot":"overwrite","input_tokens":120,"output_tokens":50,"total_tokens":170,"model_reported":"fixture-version","response_id":"synthetic-response"}') from fixture;
select pg_temp.ok('initial prompt and model immutable',(select a.prompt_snapshot='synthetic instructions' and a.model_requested='fixture' from public.resume_job_attempts a join fixture f on f.job=a.job_id));
select pg_temp.ok('usage retained separately from model confidence',(select input_tokens=120 and output_tokens=50 and total_tokens=170 from public.resume_job_attempts a join fixture f on f.job=a.job_id));
select pg_temp.denied('negative usage rejected',$q$select public.record_resume_analysis(job,token,'{"input_tokens":-1}') from fixture$q$);
select pg_temp.denied('empty result cannot be marked completed',$q$select public.settle_resume_job(job,token,'succeeded','{}') from fixture$q$);
select pg_temp.denied('required review cannot be marked completed',$q$select public.settle_resume_job(job,token,'succeeded','{"schema_version":"2","evidencias":[],"resumo_profissional":{},"experiencias":[],"skills":[],"controle_qualidade":{"motivos_revisao":["email"]}}') from fixture$q$);
select public.settle_resume_job(job,token,'review','{"schema_version":"2","nome_completo":null,"email":null,"telefone":null,"data_nascimento":null,"localizacao":null,"anos_experiencia_total":null,"evidencias":[],"resumo_profissional":{},"experiencias":[],"skills":[],"controle_qualidade":{"motivos_revisao":["nome_completo"]}}') from fixture;
select pg_temp.ok('completed attempt retains sanitized extraction snapshot',(select extraction->>'schema_version'='2' and duration_ms>=0 and finished_at is not null from public.resume_job_attempts a join fixture f on f.job=a.job_id));
select pg_temp.ok('missing name is not invented from filename',(select c.nome is null and c.anos_experiencia is null from public.candidates c join fixture f on f.company=c.company_id));
select pg_temp.ok('stale attempt cannot modify audit',not public.record_resume_analysis(job,token,'{"total_tokens":1}')) from fixture;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',actor,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('authorized company can read analysis audit',(select count(*)=1 from public.resume_job_attempts));
select pg_temp.denied('client cannot forge model or usage','update public.resume_job_attempts set total_tokens=0');
select pg_temp.denied('client cannot call audit writer',$q$select public.record_resume_analysis(job,token,'{}') from fixture$q$);
reset role;
delete from public.company_members where company_id in (select company from fixture);
set local role authenticated;
select pg_temp.ok('revoked member cannot read analysis or prompt',(select count(*)=0 from public.resume_job_attempts));
reset role;
select json_build_object('passed',count(*),'tests',json_agg(name)) as results from results;
rollback;
